using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    // Bronze customer is charged the reduced basket total
    [Theory]
    [InlineData(10000, 9500)]
    [InlineData(7, 7)]
    public void Bronze_customer_is_charged_the_reduced_basket_total(int subtotalCents, int chargedCents)
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, LoyaltyTier.Bronze));

        Assert.Equal(chargedCents, quote.TotalCents);
    }
}

